   it beat show through, and keeping the stack INSIDE the slot is what stops it
   reaching into the next night's column. */
.sch-slot--stacked .sch-show { inset-inline-end: 18px; }
.sch-show {
  position: absolute; inset: 0;
  flex-direction: column; justify-content: center; gap: 1px;
  padding: 3px 5px 3px 9px;
  cursor: default; overflow: hidden; z-index: 2;
