.sch-slot:hover .sch-show { box-shadow: 0 5px 14px rgba(16, 24, 40, 0.18); }
/* Only the name and its meta are the link out to the festival's own page. */
.sch-open {
  display: flex; flex-direction: column; gap: 1px; min-width: 0;
  text-decoration: none; color: var(--ink); cursor: pointer;
}
.sch-open:hover .sch-name { text-decoration: underline; }
.sch-show .sch-name { -webkit-line-clamp: 1; }
.sch-show:not(.sch-show--tight) .sch-name { -webkit-line-clamp: 2; }

/* The shows this hour turned down, fanned out behind the one that took it, so
   how contested an hour was is something the calendar shows rather than
   something it says. The stack covers the whole slot but sits behind the card,
   so its hit area is exactly the band and the edges it leaves showing —
   clicking there asks for the hour to go to somebody else. */
.sch-stack {
  position: absolute; inset: 0; z-index: 1;
  padding: 0; border: 0; background: transparent; cursor: pointer;
}
