/* A show's popup leads with its picture, edge to edge across the top. */
.cal-pop--preview { width: 280px; }
.pop-art {
  margin: -8px -10px 8px;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border-radius: 10px 10px 0 0;
  background: color-mix(in srgb, var(--muted) 12%, var(--paper));
}
.pop-art img { display: block; width: 100%; height: 100%; object-fit: cover; }
.pop-art--emoji {
  aspect-ratio: 3 / 1;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--festival-colour, var(--violet)) 22%, var(--paper));
  font-size: 2.2rem;
  line-height: 1;
}
.cal-pop .pop-where { margin: 0 0 4px; color: var(--muted); font-size: 0.64rem; }
.cal-pop .pop-about {
  margin: 0 0 2px;
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.cal-pop .pop-link {
  display: inline-block;
  margin: 0 0 6px;
  color: var(--violet-dark, var(--violet));
  font-size: 0.64rem;
  font-weight: 600;
}
.cal-pop .pop-foot { margin: 6px 0 0; color: var(--muted); font-size: 0.62rem; }
.cal-pop .pop-more { margin: 4px 0 0; color: var(--muted); font-size: 0.66rem; }
.panel-more { margin: 6px 8px 2px; color: var(--muted); font-size: 0.72rem; line-height: 1.35; }
.pop-nights, .pop-rivals { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.pop-night {
  display: flex; align-items: baseline; justify-content: space-between; gap: 10px;
  padding: 2px 6px; border-radius: 6px; font-variant-numeric: tabular-nums;
}
.pop-night.is-drafted { background: color-mix(in srgb, var(--ok) 15%, transparent); font-weight: 700; }
.pop-night.is-rejected { color: var(--muted); }
.pop-night.is-rejected .pn-when { text-decoration: line-through; }
.pn-note { flex: 0 0 auto; font-size: 0.6rem; color: var(--muted); font-weight: 400; }
.pop-rival {
  display: flex; align-items: baseline; justify-content: space-between; gap: 10px;
  width: 100%; text-align: start;
  font: inherit; padding: 4px 6px; border-radius: 6px;
  border: 1px solid transparent; background: transparent; color: inherit; cursor: pointer;
}
.pop-rival:hover { border-color: var(--violet); background: color-mix(in srgb, var(--violet) 8%, transparent); }
.pr-nights { flex: 0 0 auto; font-size: 0.6rem; color: var(--muted); }

/* How few nights the show has — the reason it holds the hour, said where
   there is room to say it in words. */
.pop-rarity {
  display: inline-block;
  font-size: 0.6rem; font-weight: 700; line-height: 1.6;
  padding: 0 6px; border-radius: 999px;
  background: color-mix(in srgb, var(--muted) 14%, transparent);

    if (keep && keep.kind !== "festival") {
      body.appendChild(keepBlock(iso, keep, axisH, y(state.dayStartMin)));
    } else {
      if (keep) body.appendChild(keepBanner(iso, keep, y(state.dayStartMin)));
      for (const block of own) body.appendChild(ownBlock(block, y));
      for (let i2 = 0; i2 < day.slots.length - 1; i2++) {
        const a = day.slots[i2];
        const b = day.slots[i2 + 1];
        const gap = b.startMinuteOfDay - a.endMinuteOfDay;
        if (gap < 0 || gap >= 60) continue;
        body.appendChild(buildTravelLeg(a, b, y(a.endMinuteOfDay), y(b.startMinuteOfDay)));
      }
      day.slots.forEach((slot, i2) => {
        // A short show is drawn at SCH_MIN_BLOCK so its four verdicts fit — but
        // never past the next block's own start, or the two would overlap and
        // the calendar would claim a clash the scheduler took care to avoid.
        const next = day.slots[i2 + 1];
        const ceiling = next ? y(next.startMinuteOfDay) - 2 : axisH;
        body.appendChild(
          buildScheduleBlock(slot, y(slot.startMinuteOfDay), y(slot.endMinuteOfDay), ceiling)
        );
      });
    }

    col.append(head, body);
    host.appendChild(col);
  });

  host.appendChild(buildBlockers(axis, y, gutter.getBoundingClientRect().width));
  markColumnWidth();
